import java.io.*;
import java.util.*;

public class Solution {

  public static void main(String[] args) throws IOException {
    Scanner sc = new Scanner(System.in);
    String s = sc.nextLine();
    int n = s.length();
    if (
      (s.charAt(0) == '0' || s.charAt(0) == '_' || s.charAt(0) == 'X') &&
      s.length() == 1
    ) {
      System.out.println("1");
    } else if (s.length() == 1) {
      System.out.println("0");
    } else if (s.charAt(0) == '0') {
      System.out.println("0");
    } else {
      String[] digits = { "25", "50", "75", "00" };
      String[] arr1 = { "__", "_X", "X_", "XX" };
      int[] way = { 4, 4, 4, 1 };
      way[1] = s.charAt(0) == 'X' ? 2 : 4;
      way[2] = s.charAt(0) == 'X' ? 3 : 4;
      way[0] = s.length() == 2 ? 3 : way[0];
      way[1] = s.length() == 2 ? 3 : way[1];
      int ways = 0;
      String v = s.substring(n - 2, n);
      for (int i = 0; i < 4; i++) {
        if (v.equals(digits[i])) {
          ways = 1;
        }
      }
      if (v.charAt(0) == '_' || v.charAt(0) == 'X') {
        ways = 2;
        if (v.charAt(1) == '0' && s.charAt(0) == 'X') {
          ways = 1;
        }
      } else if (v.charAt(1) == '_' || v.charAt(1) == 'X') {
        ways = 1;
      }
      for (int i = 0; i < 4; i++) {
        if (v.equals(arr1[i])) {
          ways = way[i];
        }
      }
      if (v.equals("XX") && s.charAt(0) == 'X') {
        ways = 0;
      }

      if (
        v.charAt(0) != '2' &&
        v.charAt(0) != '5' &&
        v.charAt(0) != '7' &&
        v.charAt(0) != '0' &&
        v.charAt(0) != 'X' &&
        v.charAt(0) != '_'
      ) {
        ways = 0;
      }
      if (
        v.charAt(1) != '0' &&
        v.charAt(1) != '5' &&
        v.charAt(1) != 'X' &&
        v.charAt(1) != '_'
      ) {
        ways = 0;
      }

      boolean ok = false;
      long toti = 1L;
      for (int i = 0; i < s.length() - 2; i++) {
        if (s.charAt(i) == 'X') {
          ok = true;
        }
        if (s.charAt(i) == '_') {
          if (i == 0) {
            toti *= 9L;
          } else {
            toti *= 10L;
          }
        }
      }
      if (v.charAt(0) != 'X' && v.charAt(1) != 'X') {
        if (ok) {
          if (s.charAt(0) == 'X') {
            toti *= 9L;
          } else {
            toti *= 10L;
          }
        }
      }
      toti *= ways;
      System.out.println(toti);
    }
  }
}
